---The daemon's verbs as Lua functions, bound from its contracts (autodoc.contracts, generated by
---go generate ./rpc from the binary's own catalog). A domain's functions take the verb's params in
---order, then `cb(result, err)`; a call with the wrong count of params, or no callback, raises at
---the call, before anything reaches the daemon. The protocol's own verbs (audience "internal":
---sys.hello, sys.shutdown) are never bound.
---@module 'autodoc.contract'

local contracts = require("autodoc.contracts")

local M = {}

-- The protocol the contracts are at: this plugin's (autodoc.client).
M.PROTOCOL = contracts.protocol

---params is a verb's params as names, in order, a trailing "?" marking an optional one; nil for a
---verb the contracts do not have.
---@param verb string "todos.get"
---@return string[]|nil
function M.params(verb)
  local c = contracts.verbs[verb]
  if not c then return nil end
  local out = {}
  for i, p in ipairs(c.params) do
    out[i] = p.name .. (p.optional and "?" or "")
  end
  return out
end

---domain is every bindable verb of a domain, by its own name ("get" for todos.get), each with its
---params as M.params gives them.
---@param name string "todos"
---@return table<string, string[]>
function M.domain(name)
  local out, prefix = {}, name .. "."
  for verb, c in pairs(contracts.verbs) do
    if verb:sub(1, #prefix) == prefix and c.audience ~= "internal" then
      out[verb:sub(#prefix + 1)] = M.params(verb)
    end
  end
  return out
end

---required is how many of params a call must give.
---@param params string[]
---@return integer
local function required(params)
  for i, p in ipairs(params) do
    if p:sub(-1) == "?" then return i - 1 end
  end
  return #params
end

---bind puts a function on target for each of verbs (as M.domain gives them) that checks its params
---and its callback, then hands call the verb's own name and its params as a list.
---@param target table
---@param label string what errors name the functions by: "autodoc.todos"
---@param verbs table<string, string[]>
---@param call fun(verb: string, params: any[], cb: function)
function M.bind(target, label, verbs, call)
  for verb, params in pairs(verbs) do
    local lo, hi = required(params), #params
    target[verb] = function(...)
      local args = { ... }
      local n = select("#", ...)
      local cb = args[n]
      if type(cb) ~= "function" then
        error(string.format("%s.%s: the last argument is the callback", label, verb), 2)
      end
      n = n - 1
      -- trailing nils are params left out
      while n > 0 and args[n] == nil do n = n - 1 end
      if n < lo or n > hi then
        error(string.format("%s.%s takes %d to %d params (%s), then a callback; got %d",
          label, verb, lo, hi, table.concat(params, ", "), n), 2)
      end
      local list = {}
      for i = 1, n do list[i] = args[i] end
      call(verb, list, cb)
    end
  end
end

return M
